/* aesthetic registers v2.16.0 — generated by scripts/build-registry.mjs. */
@import './aesthetic.base.css';

:root {
  --ae-ink-muted: #737373;
  --ae-ink-muted-dark: #8f8f8f;
  --ae-w-medium: 550;
  --ae-w-black: 800;
}

@media (prefers-color-scheme: dark) {
  :root:not(.light):not([data-ae-mode='light']) {
    --ae-ink-muted: var(--ae-ink-muted-dark);
  }
}

.light,
[data-ae-mode='light'] {
  color-scheme: light;
}

.dark,
[data-ae-mode='dark'] {
  color-scheme: dark;
  --ae-ink-muted: var(--ae-ink-muted-dark);
}

.ae-name {
font-weight: var(--ae-w-black);
  letter-spacing: 0.38em;
}

a.ae-name {
text-decoration: none;
}

.ae-lede {
max-width: 34em;
  text-wrap: pretty;
}

.ae-item {
font-weight: var(--ae-w-medium);
}

.ae-dim {
color: var(--ae-ink-muted);
}

.ae-accent {
color: var(--ae-accent);
  font-weight: var(--ae-w-medium);
  text-decoration: underline;
  text-decoration-color: currentColor;
  text-underline-offset: 0.2em;
}
